setSafety.text:
const setSafety = (
    next: CatalogSafetyGate | null,
    expected?: CatalogSafetyGate,
  ): boolean => {
    const stored = catalogSafetyStorage();
    if (!stored) {
      setStorageUnavailable(true);
      runtime.queryClient.setQueryData(
        safetyKey,
        expected ?? next ?? safety ?? null,
      );
      return false;
    }
    const current = stored
      ? readCatalogSafetyGate(stored, ownerId, config.id)
      : null;
    if (expected && JSON.stringify(current) !== JSON.stringify(expected)) {
      runtime.queryClient.setQueryData(
        safetyKey,
        current ?? { phase: 'inspection' },
      );
      return false;
    }
    const saved =
      stored && writeCatalogSafetyGate(stored, ownerId, config.id, next);
    if (!saved) setStorageUnavailable(true);
    runtime.queryClient.setQueryData(
      safetyKey,
      saved ? next : current ?? expected ?? next,
    );
    return Boolean(saved);
  };

beginWrite.text:
const beginWrite = (candidate: CatalogAction): CatalogSafetyGate => {
    const stored = catalogSafetyStorage();
    if (!stored) {
      setStorageUnavailable(true);
      throw new ApiError(
        'INVALID_INPUT',
        '浏览器本地存储不可用，无法安全提交。',
      );
    }
    const existing = readCatalogSafetyGate(stored, ownerId, config.id);
    if (existing) {
      runtime.queryClient.setQueryData(safetyKey, existing);
      throw new ApiError('INVALID_INPUT', '已有写入结果待核实，请先重读目录。');
    }
    const gate: CatalogSafetyGate = {
      phase: 'refresh',
      message: null,
      detailId:
        candidate.type === 'delete-group' || candidate.type === 'create-group'
          ? null
          : candidate.group.id,
      createUncertain:
        candidate.type === 'create-group' || candidate.type === 'create-asin',
      operationId: `${Date.now()}-${Math.random().toString(36).slice(2)}`,
    };
    if (!writeCatalogSafetyGate(stored, ownerId, config.id, gate)) {
      setStorageUnavailable(true);
      throw new ApiError(
        'INVALID_INPUT',
        '无法保存写入状态，请检查浏览器本地存储权限。',
      );
    }
    return gate;
  };

reconcileCreate.text:
async function reconcileCreate() {
    if (safety?.phase !== 'inspection') return;
    let reconciled = false;
    try {
      await runWithCatalogLock(async () => {
        const stored = catalogSafetyStorage();
        const current = stored
          ? readCatalogSafetyGate(stored, ownerId, config.id)
          : null;
        if (!stored) {
          setStorageUnavailable(true);
          return;
        }
        if (!current) {
          await readAfterWrite(null);
          const latest = readCatalogSafetyGate(stored, ownerId, config.id);
          runtime.queryClient.setQueryData(safetyKey, latest);
          reconciled = !latest;
          return;
        }
        if (JSON.stringify(current) !== JSON.stringify(safety)) {
          runtime.queryClient.setQueryData(safetyKey, current);
          return;
        }
        await readAfterWrite(null);
        reconciled = setSafety(null, safety);
      });
      if (!reconciled) return;
      setNotice('目录已重新读取，请仅在确认原新建记录后继续写入。');
    } catch (cause) {
      if (catalogAccessDenied(cause)) reportAccessDenied();
      else setNotice('目录重读失败，写入仍暂停，请稍后重试。');
    }
  }

unlockAfterReconciliation.text:
async function unlockAfterReconciliation() {
    if (!canReconcile) return;
    const stored = storage();
    const locks = navigator.locks;
    if (!stored || !locks || !gate) {
      setNotice('无法清除导入锁，请检查浏览器本地存储权限。');
      return;
    }
    const expected = gate;
    let result: 'changed' | 'cleared' | 'unavailable' | 'active';
    try {
      const key = importGateKey(domain, userId);
      const previousRaw = stored.getItem(key);
      result = await locks.request(key, () => {
        if (
          latestTask.current?.taskId === expected.taskId &&
          isActiveTask(latestTask.current.status)
        )
          return 'active' as const;
        if (
          latestTask.current?.taskId === expected.taskId &&
          isTerminalTask(latestTask.current.status) &&
          expected.phase !== 'settled'
        )
          return 'changed' as const;
        const current = readImportGate(stored, domain, userId);
        const session = storage('session');
        const sessionGate = session
          ? readImportGate(session, domain, userId)
          : null;
        const matchesUnsavedGate =
          expected.phase === 'uncertain' &&
          expected.taskId &&
          ((current?.phase === 'uncertain' &&
            current.taskId === null &&
            current.savedAt === expected.savedAt) ||
            (!current &&
              JSON.stringify(sessionGate) === JSON.stringify(expected)));
        if (
          stored.getItem(key) !== previousRaw ||
          (JSON.stringify(current) !== JSON.stringify(expected) &&
            !matchesUnsavedGate)
        )
          return 'changed' as const;
        return writeImportGate(stored, domain, userId, null)
          ? ('cleared' as const)
          : ('unavailable' as const);
      });
    } catch {
      result = 'unavailable';
    }
    if (owner.current !== userId || !mounted.current) return;
    if (result === 'active') {
      setNotice('原导入任务仍在运行，结束前不能解锁或重新导入。');
      return;
    }
    if (result !== 'cleared') {
      setGate(restoredGate(stored, domain, userId));
      setNotice(
        result === 'changed'
          ? '原任务状态已变化，请重新核实后再解锁。'
          : '无法清除导入锁，请检查浏览器本地存储权限。',
      );
      return;
    }
    const session = storage('session');
    if (session && !writeImportGate(session, domain, userId, null)) {
      setNotice('无法清除导入锁，请检查浏览器会话存储权限。');
      return;
    }
    setGate(null);
    setLastTaskId(null);
    setFile(null);
    if (fileInput.current) fileInput.current.value = '';
    setNotice('请确认原任务不会继续写入后再重新导入。');
  }
